"""The planner of the MPVI pipeline: one structured Gemini call from the instruction to the plan (design plan 8).

    planner = make_llm_planner(caller.bind("plan", LLM_CFG["planner_prompt_version"]))
    plan = planner("put the beaker on the hotplate")     # a dict in the paper's segment format (src/mpvi_schemas.Plan)

The reply is enforced by the Plan schema at the provider and validated again here; a reply that does not fit raises PlannerError and the plan does not start. The prompt text is in
src/mpvi_prompts.py (the paper's Appendix D Task Planning Prompt, verbatim: the instruction is its {task_description}; it names no locations, so a navigation target is whatever phrase the LLM writes).
"""

from pydantic import ValidationError

from src.mpvi_prompts import PLANNER_PROMPT, fill_prompt
from src.mpvi_schemas import Plan


class PlannerError(ValueError):
    """The planner's reply is not a valid plan."""


def make_llm_planner(structured_call):
    """Builds the planner on a structured-output call.

    Args:
        structured_call (callable): structured_call(prompt, response_model) -> dict (GeminiCaller.bind).

    Returns:
        callable: planner(instruction) -> plan dict.
    """
    def planner(instruction):
        reply = structured_call(fill_prompt(PLANNER_PROMPT, task_description=instruction.strip()), Plan)
        try:
            return Plan.model_validate(reply).model_dump(mode="json")
        except ValidationError as e:
            raise PlannerError(f"the planner's reply does not fit the plan schema: {e}") from e
    return planner
